(function () {
  'use strict';

  var NL = String.fromCharCode(10);
  var rawCode = '';
  var matches = [];
  var currentMatch = -1;
  var isMaximized = false;
  var prevSize = null;
  var preMinimizeSize = null;
  var saveTimer = null;
  var rescanTimer = null;
  var scrollRaf = null;
  var toastTimer = null;
  var isDesktop = (window.innerWidth || 0) >= 768;
  var isBallMode = false;
  var isSearchCollapsed = false;

  var MIN_W = 240, MIN_H = 320;
  var MAX_W = 420, MAX_H = 520;
  var BALL_SIZE = 36;
  var IDLE_DELAY = 3000;
  var winW = 320, winH = 500;

  function $(id) { return document.getElementById(id); }
  function escapeHTML(s) {
    return String(s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
  }

  var resizeRaf = null, pendingSize = null;
  function flushResize() {
    resizeRaf = null;
    if (!pendingSize) return;
    var p = pendingSize; pendingSize = null;
    try { if (window.nuo && window.nuo.window && window.nuo.window.resize) window.nuo.window.resize(p.w, p.h); } catch (e) {}
  }
  function setWindowSize(w, h, noClamp) {
    if (!noClamp) { w = Math.max(MIN_W, Math.min(MAX_W, Math.round(w))); h = Math.max(MIN_H, Math.min(MAX_H, Math.round(h))); }
    else { w = Math.max(1, Math.round(w)); h = Math.max(1, Math.round(h)); }
    winW = w; winH = h;
    pendingSize = { w: w, h: h };
    if (resizeRaf === null) resizeRaf = requestAnimationFrame(flushResize);
  }

  var idleTimer = null;
  function clearIdle() { clearTimeout(idleTimer); idleTimer = null; if (document.body.classList.contains('idle')) document.body.classList.remove('idle'); }
  function startIdleCountdown() { clearIdle(); idleTimer = setTimeout(function () { if (isBallMode) document.body.classList.add('idle'); }, IDLE_DELAY); }
  function kickIdle() {
    if (document.body.classList.contains('idle')) document.body.classList.remove('idle');
    if (isBallMode) startIdleCountdown();
    else { clearTimeout(idleTimer); idleTimer = null; }
  }
  ['pointerdown','pointermove','pointerup','pointercancel','keydown','keyup','input','focusin','wheel','touchstart','touchmove','touchend','scroll'].forEach(function (ev) {
    document.addEventListener(ev, kickIdle, { passive: true, capture: true });
  });

  function updateMaximizeButton() {
    var btn = $('btn-maximize'); if (!btn) return;
    if (isMaximized) { btn.textContent = '还原'; btn.classList.add('active'); }
    else { btn.textContent = '最大化'; btn.classList.remove('active'); }
  }
  function exitMaximizeFlag() { if (!isMaximized) return; isMaximized = false; document.body.classList.remove('maximized'); updateMaximizeButton(); }
  function toggleMaximize() {
    if (!isMaximized) {
      prevSize = { w: winW, h: winH };
      setWindowSize(MAX_W, MAX_H);
      isMaximized = true;
      document.body.classList.add('maximized');
    } else {
      if (prevSize) setWindowSize(prevSize.w, prevSize.h); else setWindowSize(320, 500);
      isMaximized = false;
      document.body.classList.remove('maximized');
    }
    updateMaximizeButton();
    requestAnimationFrame(function () { syncPadding(); syncScroll(); });
  }

  function minimizeApp() {
    exitMaximizeFlag();
    preMinimizeSize = { w: winW, h: winH };
    isBallMode = true;
    document.body.classList.add('ball');
    setWindowSize(BALL_SIZE, BALL_SIZE, true);
    startIdleCountdown();
  }
  function restoreApp() {
    isBallMode = false;
    document.body.classList.remove('ball');
    clearIdle();
    if (preMinimizeSize) { setWindowSize(preMinimizeSize.w, preMinimizeSize.h, true); preMinimizeSize = null; }
    else setWindowSize(320, 500);
    /* 从球态恢复：强制展开搜索栏 */
    isSearchCollapsed = false;
    updateSearchBarVisibility();
    requestAnimationFrame(function () { syncPadding(); syncScroll(); });
  }
  function closeApp() {
    try { if (window.nuo && window.nuo.window) window.nuo.window.close(); } catch (e) {}
  }

  try {
    if (window.nuo && window.nuo.window && window.nuo.window.dragHandle) {
      var dh = $('drag-header');
      if (dh) window.nuo.window.dragHandle(dh);
      var ball = $('floating-ball');
      if (ball) window.nuo.window.dragHandle(ball);
    }
  } catch (e) {}

  (function () {
    var ball = $('floating-ball');
    if (!ball) return;
    ball.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      restoreApp();
    });
  })();

  (function () {
    var handle = $('resize-handle');
    if (!handle) return;
    var resizing = null;
    handle.addEventListener('pointerdown', function (e) {
      if (e.button !== undefined && e.button !== 0) return;
      e.preventDefault(); e.stopPropagation();
      resizing = { id: e.pointerId, startX: e.clientX, startY: e.clientY, startW: winW, startH: winH };
      try { handle.setPointerCapture(e.pointerId); } catch (err) {}
      document.body.classList.add('resizing');
    });
    handle.addEventListener('pointermove', function (e) {
      if (!resizing || e.pointerId !== resizing.id) return;
      setWindowSize(resizing.startW + (e.clientX - resizing.startX), resizing.startH + (e.clientY - resizing.startY));
    });
    function endResize(e) {
      if (!resizing || e.pointerId !== resizing.id) return;
      resizing = null;
      document.body.classList.remove('resizing');
      if (isMaximized && (winW !== MAX_W || winH !== MAX_H)) exitMaximizeFlag();
      requestAnimationFrame(function () { syncPadding(); syncScroll(); });
    }
    handle.addEventListener('pointerup', endResize);
    handle.addEventListener('pointercancel', endResize);
    handle.addEventListener('lostpointercapture', function (e) { if (resizing && e.pointerId === resizing.id) endResize(e); });
  })();

  var taPaste = $('code-input');
  var taEdit = $('edit-area');
  var highlight = $('highlight-layer');
  var searchInput = $('search-input');
  var searchStatus = $('search-status');
  var searchDropdown = $('search-dropdown');
  var searchBar = $('search-bar');
  var btnCollapse = $('btn-collapse-search');
  var btnExpand = $('btn-expand-search');
  var toastEl = $('app-toast');

  function showToast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { toastEl.classList.remove('show'); }, 1500);
  }

  function getActiveTextarea() {
    return $('panel-view').classList.contains('active') ? taEdit : taPaste;
  }

  function doSelectAll() {
    var el = getActiveTextarea();
    var text = el.value || '';
    if (!text) { showToast('没有内容'); return; }
    try { el.focus({ preventScroll: true }); }
    catch (e) { try { el.focus(); } catch (e2) {} }
    try { el.setSelectionRange(0, text.length); } catch (e) { try { el.select(); } catch (e2) {} }
    showToast('已全选 ' + text.length + ' 字符');
  }

  function copyViaFallback(text) {
    try {
      var tmp = document.createElement('textarea');
      tmp.value = text;
      tmp.style.position = 'fixed';
      tmp.style.left = '-9999px';
      tmp.style.top = '0';
      tmp.style.opacity = '0';
      tmp.setAttribute('readonly', '');
      document.body.appendChild(tmp);
      tmp.select();
      tmp.setSelectionRange(0, text.length);
      var ok = false;
      try { ok = document.execCommand('copy'); } catch (e) {}
      document.body.removeChild(tmp);
      return ok;
    } catch (e) { return false; }
  }

  function doCopy() {
    var el = getActiveTextarea();
    var text = el.value || '';
    if (!text) { showToast('没有内容'); return; }
    var fallbackAfterAsync = function () {
      if (copyViaFallback(text)) showToast('已复制 ' + text.length + ' 字符');
      else showToast('复制失败');
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      try {
        navigator.clipboard.writeText(text).then(function () {
          showToast('已复制 ' + text.length + ' 字符');
        }).catch(function () {
          fallbackAfterAsync();
        });
      } catch (e) {
        fallbackAfterAsync();
      }
    } else {
      fallbackAfterAsync();
    }
  }

  /* ============ 搜索栏显示控制 ============ */
  function updateSearchBarVisibility() {
    var onViewTab = $('panel-view').classList.contains('active');
    if (!onViewTab) {
      /* 离开搜索查看标签时，重置收起状态，保证下次回来搜索栏会显示 */
      isSearchCollapsed = false;
      searchBar.style.display = 'none';
      btnExpand.classList.remove('visible');
      return;
    }
    if (isSearchCollapsed) {
      searchBar.style.display = 'none';
      btnExpand.classList.add('visible');
    } else {
      searchBar.style.display = 'flex';
      btnExpand.classList.remove('visible');
    }
  }
  function collapseSearch() {
    if (isSearchCollapsed) return;
    isSearchCollapsed = true;
    updateSearchBarVisibility();
    searchDropdown.style.display = 'none';
    try { taEdit.focus({ preventScroll: true }); }
    catch (e) { try { taEdit.focus(); } catch (e2) {} }
  }
  function expandSearch() {
    if (!isSearchCollapsed) { try { searchInput.focus(); } catch (e) {} return; }
    isSearchCollapsed = false;
    updateSearchBarVisibility();
    try { searchInput.focus(); } catch (e) {}
    var v = searchInput.value || '';
    try { searchInput.setSelectionRange(v.length, v.length); } catch (e) {}
  }
  btnCollapse.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); collapseSearch(); });
  btnExpand.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); expandSearch(); });

  try {
    if (window.nuo && window.nuo.storage) {
      window.nuo.storage.get('code').then(function (v) {
        if (typeof v === 'string' && v) {
          taPaste.value = v; taEdit.value = v; rawCode = v; renderHighlight();
        }
      }).catch(function () {});
    }
  } catch (e) {}
  function persistCode(text) {
    try { if (window.nuo && window.nuo.storage) window.nuo.storage.set('code', text).catch(function () {}); } catch (e) {}
  }
  function scheduleSave(text) { clearTimeout(saveTimer); saveTimer = setTimeout(function () { persistCode(text); }, 500); }
  taPaste.addEventListener('input', function () { rawCode = taPaste.value; scheduleSave(rawCode); });

  function syncScroll() {
    if (scrollRaf) return;
    scrollRaf = requestAnimationFrame(function () {
      scrollRaf = null;
      highlight.scrollTop = taEdit.scrollTop;
      highlight.scrollLeft = taEdit.scrollLeft;
    });
  }
  function syncPadding() {
    var sbw = taEdit.offsetWidth - taEdit.clientWidth;
    if (sbw < 0) sbw = 0;
    highlight.style.paddingRight = (12 + sbw) + 'px';
  }
  taEdit.addEventListener('scroll', syncScroll, { passive: true });

  function renderHighlight() {
    var text = taEdit.value;
    if (matches.length === 0) { highlight.textContent = text + NL; return; }
    var html = '';
    var pos = 0;
    for (var i = 0; i < matches.length; i++) {
      var m = matches[i];
      if (m.start > pos) html += escapeHTML(text.substring(pos, m.start));
      var cls = (i === currentMatch) ? ' class="current"' : '';
      html += '<mark' + cls + '>' + escapeHTML(text.substring(m.start, m.end)) + '</mark>';
      pos = m.end;
    }
    if (pos < text.length) html += escapeHTML(text.substring(pos));
    html += NL;
    highlight.innerHTML = html;
  }

  function scanMatches() {
    var q = searchInput.value;
    var text = taEdit.value;
    matches = [];
    currentMatch = -1;
    if (!q) return;
    var lq = q.toLowerCase();
    var lt = text.toLowerCase();
    var idx = 0, guard = 0;
    while (guard++ < 50000) {
      var at = lt.indexOf(lq, idx);
      if (at === -1) break;
      matches.push({ start: at, end: at + q.length });
      idx = at + Math.max(1, q.length);
    }
  }
  function scrollToCurrentMark() {
    var mEl = highlight.querySelector('mark.current');
    if (!mEl) return;
    var top = mEl.offsetTop;
    var h = taEdit.clientHeight;
    var mh = mEl.offsetHeight || 20;
    taEdit.scrollTop = Math.max(0, top - h / 2 + mh / 2);
    syncScroll();
  }
  function gotoMatch(n, focusIt) {
    if (matches.length === 0) { currentMatch = -1; searchStatus.textContent = '0/0'; renderHighlight(); return; }
    currentMatch = ((n % matches.length) + matches.length) % matches.length;
    renderHighlight();
    var m = matches[currentMatch];
    try { taEdit.setSelectionRange(m.start, m.end); } catch (e) {}
    requestAnimationFrame(function () { scrollToCurrentMark(); });
    if (focusIt !== false && isDesktop) {
      try { taEdit.focus({ preventScroll: true }); }
      catch (e) { try { taEdit.focus(); } catch (e2) {} }
    }
    searchStatus.textContent = (currentMatch + 1) + '/' + matches.length;
  }
  function buildDropdown() {
    if (matches.length === 0) { searchDropdown.innerHTML = ''; searchDropdown.style.display = 'none'; return; }
    var text = taEdit.value;
    var max = Math.min(matches.length, 200);
    var html = '';
    for (var i = 0; i < max; i++) {
      var m = matches[i];
      var lineStart = text.lastIndexOf(NL, m.start - 1) + 1;
      var lineEnd = text.indexOf(NL, m.end);
      if (lineEnd === -1) lineEnd = text.length;
      var lineIdx = text.substring(0, m.start).split(NL).length;
      var before = text.substring(Math.max(lineStart, m.start - 20), m.start);
      var midText = text.substring(m.start, m.end);
      var after = text.substring(m.end, Math.min(lineEnd, m.end + 30));
      var preDot = (m.start - 20 > lineStart) ? '…' : '';
      var sufDot = (m.end + 30 < lineEnd) ? '…' : '';
      html += '<div class="drop-item" data-idx="' + i + '">' + '<span class="drop-num">' + lineIdx + '</span>' + escapeHTML(preDot + before) + '<mark>' + escapeHTML(midText) + '</mark>' + escapeHTML(after + sufDot) + '</div>';
    }
    searchDropdown.innerHTML = html;
    searchDropdown.style.display = 'block';
  }

  searchInput.addEventListener('input', function () {
    scanMatches();
    if (matches.length > 0) { gotoMatch(0); buildDropdown(); }
    else { searchStatus.textContent = '0/0'; searchDropdown.innerHTML = ''; searchDropdown.style.display = 'none'; renderHighlight(); }
  });
  searchInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') { e.preventDefault(); if (matches.length > 0) gotoMatch(currentMatch + 1); }
    else if (e.key === 'Escape') {
      e.preventDefault();
      if (searchInput.value) {
        searchInput.value = ''; matches = []; currentMatch = -1;
        searchStatus.textContent = '0/0';
        searchDropdown.innerHTML = ''; searchDropdown.style.display = 'none';
        renderHighlight();
      } else { collapseSearch(); }
    }
  });
  searchInput.addEventListener('focus', function () { if (matches.length > 0) searchDropdown.style.display = 'block'; });
  searchInput.addEventListener('blur', function () { setTimeout(function () { searchDropdown.style.display = 'none'; }, 200); });

  $('btn-prev').addEventListener('click', function () { if (matches.length === 0) return; gotoMatch(currentMatch - 1); });
  $('btn-next').addEventListener('click', function () { if (matches.length === 0) return; gotoMatch(currentMatch + 1); });

  searchDropdown.addEventListener('mousedown', function (e) {
    var node = e.target;
    while (node && node !== this && !(node.classList && node.classList.contains('drop-item'))) node = node.parentNode;
    if (!node || node === this) return;
    e.preventDefault();
    var idx = parseInt(node.getAttribute('data-idx'), 10);
    if (isNaN(idx)) return;
    gotoMatch(idx);
    searchDropdown.style.display = 'none';
  });

  taEdit.addEventListener('input', function () {
    rawCode = taEdit.value;
    scheduleSave(rawCode);
    if (!searchInput.value) { renderHighlight(); return; }
    clearTimeout(rescanTimer);
    rescanTimer = setTimeout(function () {
      var selStart = taEdit.selectionStart;
      scanMatches();
      if (matches.length === 0) {
        searchStatus.textContent = '0/0';
        searchDropdown.innerHTML = ''; searchDropdown.style.display = 'none';
        renderHighlight(); return;
      }
      var found = -1;
      for (var i = 0; i < matches.length; i++) {
        if (matches[i].start <= selStart && selStart <= matches[i].end) { found = i; break; }
      }
      if (found >= 0) currentMatch = found;
      else if (currentMatch >= matches.length) currentMatch = matches.length - 1;
      else if (currentMatch < 0) currentMatch = 0;
      searchStatus.textContent = (currentMatch + 1) + '/' + matches.length;
      renderHighlight();
      if (searchInput.value) buildDropdown();
    }, 120);
  });

  function switchTab(tab) {
    if (tab === 'view') {
      if (taEdit.value !== taPaste.value) taEdit.value = taPaste.value;
      rawCode = taEdit.value;
      /* 切到搜索查看：重置收起状态，保证搜索栏可见 */
      isSearchCollapsed = false;
      requestAnimationFrame(function () {
        syncPadding();
        scanMatches();
        if (matches.length > 0) { gotoMatch(currentMatch >= 0 ? currentMatch : 0); buildDropdown(); }
        else { renderHighlight(); searchStatus.textContent = '0/0'; }
      });
    } else {
      if (taPaste.value !== taEdit.value) taPaste.value = taEdit.value;
    }
    $('tab-edit').classList.toggle('active', tab === 'edit');
    $('tab-view').classList.toggle('active', tab === 'view');
    $('panel-edit').classList.toggle('active', tab === 'edit');
    $('panel-view').classList.toggle('active', tab === 'view');
    updateSearchBarVisibility();
  }
  $('tab-edit').addEventListener('click', function () { switchTab('edit'); });
  $('tab-view').addEventListener('click', function () { switchTab('view'); });

  function clearAll() {
    taPaste.value = ''; taEdit.value = ''; rawCode = '';
    persistCode('');
    searchInput.value = ''; matches = []; currentMatch = -1;
    searchStatus.textContent = '0/0';
    searchDropdown.innerHTML = ''; searchDropdown.style.display = 'none';
    renderHighlight();
    switchTab('edit');
    showToast('已清空');
  }

  window.addEventListener('resize', function () { requestAnimationFrame(function () { syncPadding(); syncScroll(); }); });

  $('btn-minimize').addEventListener('click', minimizeApp);
  $('btn-clear').addEventListener('click', clearAll);
  $('btn-maximize').addEventListener('click', toggleMaximize);
  $('btn-close').addEventListener('click', closeApp);
  $('btn-select-all').addEventListener('click', doSelectAll);
  $('btn-copy').addEventListener('click', doCopy);

  updateMaximizeButton();
  isBallMode = false;
  clearIdle();
  updateSearchBarVisibility();

  requestAnimationFrame(function () { syncPadding(); renderHighlight(); });

  try { if (window.nuo && window.nuo.ready) window.nuo.ready(); } catch (e) {}
})();

